/**
 * Unit tests for BeanDeserializerBase#deserializeFromObjectId
 */
public class BeanDeserializerBase_deserializeFromObjectId_TriageGen2Test {

    private BeanDeserializerBase beanDeserializerBase;
    private JsonParser mockParser;
    private DeserializationContext mockContext;
    private ObjectIdReader mockObjectIdReader;
    private ReadableObjectId mockReadableObjectId;
    private JsonLocation mockLocation;

    @Before
    public void setUp() throws IOException {
        mockParser = mock(JsonParser.class);
        mockContext = mock(DeserializationContext.class);
        mockObjectIdReader = mock(ObjectIdReader.class);
        mockReadableObjectId = mock(ReadableObjectId.class);
        mockLocation = mock(JsonLocation.class);

        // We use the constructor that accepts ObjectIdReader
        // Since BeanDeserializerBase is abstract, we must mock it or use a subclass
        beanDeserializerBase = mock(BeanDeserializerBase.class, withSettings()
                .useConstructor(null, mockObjectIdReader)
                .defaultAnswer(CALLS_REAL_METHODS));

        // Setup internal field via reflection or by ensuring the constructor sets it
        // In Jackson, the constructor BeanDeserializerBase(BeanDeserializerBase src, ObjectIdReader oir) 
        // sets the _objectIdReader field.

        when(mockParser.getCurrentLocation()).thenReturn(mockLocation);
        when(mockObjectIdReader.generator()).thenReturn(null); // Simplified
        when(mockObjectIdReader.resolver()).thenReturn(null); // Simplified
    }

    @Test
    public void testDeserializeFromObjectId_Success() throws IOException {
        // Arrange
        Object expectedId = "id-123";
        Object expectedPojo = new Object();

        when(mockObjectIdReader.readObjectReference(mockParser, mockContext)).thenReturn(expectedId);
        when(mockContext.findObjectId(eq(expectedId), any(), any())).thenReturn(mockReadableObjectId);
        when(mockReadableObjectId.resolve()).thenReturn(expectedPojo);

        // Act
        Object result = beanDeserializerBase.deserializeFromObjectId(mockParser, mockContext);

        // Assert
        assertEquals(expectedPojo, result);
        verify(mockObjectIdReader).readObjectReference(mockParser, mockContext);
        verify(mockContext).findObjectId(eq(expectedId), any(), any());
        verify(mockReadableObjectId).resolve();
    }

    @Test(expected = UnresolvedForwardReference.class)
    public void testDeserializeFromObjectId_ThrowsUnresolvedForwardReference() throws IOException {
        // Arrange
        Object id = "unresolved-id";
        when(mockObjectIdReader.readObjectReference(mockParser, mockContext)).thenReturn(id);
        when(mockContext.findObjectId(eq(id), any(), any())).thenReturn(mockReadableObjectId);

        // Simulate that the object is not yet resolved (returns null)
        when(mockReadableObjectId.resolve()).thenReturn(null);

        // Act
        beanDeserializerBase.deserializeFromObjectId(mockParser, mockContext);

        // Assert via expected exception
    }

